// userProfileService.test.ts
import { UserProfileService, UserProfileError } from './userProfileService';
import fetch from 'node-fetch';

jest.mock('node-fetch');
const mockedFetch = fetch as jest.MockedFunction<typeof fetch>;

const BASE_URL = 'https://api.example.com';
const SAMPLE_PROFILE = { id: '123', name: 'Alice', email: 'alice@example.com' };

describe('UserProfileService', () => {
  let service: UserProfileService;

  beforeEach(() => {
    service = new UserProfileService(BASE_URL);
    jest.clearAllMocks();
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('fetches and caches a profile', async () => {
    mockedFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => SAMPLE_PROFILE,
    } as any);

    const p1 = await service.getProfile('123');
    expect(p1).toEqual(SAMPLE_PROFILE);
    expect(mockedFetch).toHaveBeenCalledTimes(1);

    // second call should use cache
    const p2 = await service.getProfile('123');
    expect(p2).toEqual(SAMPLE_PROFILE);
    expect(mockedFetch).toHaveBeenCalledTimes(1);
  });

  it('refetches after TTL expires', async () => {
    mockedFetch
      .mockResolvedValueOnce({ ok: true, json: async () => SAMPLE_PROFILE } as any)
      .mockResolvedValueOnce({ ok: true, json: async () => ({ ...SAMPLE_PROFILE, name: 'Bob' }) } as any);

    await service.getProfile('123');
    // advance 6 minutes
    jest.advanceTimersByTime(6 * 60 * 1000);
    const fresh = await service.getProfile('123');
    expect(fresh.name).toBe('Bob');
    expect(mockedFetch).toHaveBeenCalledTimes(2);
  });

  it('throws UserProfileError on 404', async () => {
    mockedFetch.mockResolvedValueOnce({ ok: false, status: 404 } as any);
    await expect(service.getProfile('999')).rejects.toThrow(UserProfileError);
  });

  it('throws UserProfileError on network failure', async () => {
    mockedFetch.mockRejectedValueOnce(new Error('network down'));
    await expect(service.getProfile('123')).rejects.toThrow(UserProfileError);
  });
});
```

**Validation Steps**
1. Run `npm test` – all four tests should pass.
2. Manually call `service.getProfile('123')` twice within 5 min and observe only one network request (via logs or mock).
3. Advance timers >5 min and verify a second request occurs.

**Trade‑offs**
- **In‑memory cache** – simple, zero‑dependency, but not shared across processes or restarts.
- **Hard‑coded TTL** – easy to reason about; could be made configurable for flexibility.
- **No persistence** – cache loss on redeploy; acceptable for low‑traffic internal services.
- **Error abstraction** – `UserProfileError` gives callers a single catch point but hides original `fetch` error details.

// store.go - Generic observable store
package store

type Store[T any] struct {
    mu       sync.RWMutex
    value    T
    listeners []func(T)
}

func NewStore[T any](initial T) *Store[T] {
    return &Store[T]{value: initial}
}

func (s *Store[T]) Get() T {
    s.mu.RLock()
    defer s.mu.RUnlock()
    return s.value
}

func (s *Store[T]) Set(fn func(T) T) {
    s.mu.Lock()
    s.value = fn(s.value)
    listeners := s.listeners
    s.mu.Unlock()
    for _, l := range listeners {
        l(s.value)
    }
}

func (s *Store[T]) Subscribe(listener func(T)) func() {
    s.mu.Lock()
    s.listeners = append(s.listeners, listener)
    s.mu.Unlock()
    return func() {
        s.mu.Lock()
        for i, l := range s.listeners {
            if &l == &listener { // Note: func comparison needs workaround
                s.listeners = append(s.listeners[:i], s.listeners[i+1:]...)
                break
            }
        }
        s.mu.Unlock()
    }
}

