func NewHeader() *Header {
    h := &Header{}
    // Subscribe only to User and Cart.Count via selectors
    userStore := vecty.GetContext(h, UserStoreKey).(*store.Store[*User])
    cartStore := vecty.GetContext(h, CartStoreKey).(*store.Store[*ShoppingCart])

    h.unsubUser = userStore.Subscribe(func(u *User) {
        h.currentUser = u
        vecty.Rerender(h)
