```go
package testutil

import (
    "database/sql"
    "testing"
    _ "github.com/lib/pq"
)

func NewTestDB(t *testing.T) (*sql.DB, func()) {
    t.Helper()

    dsn := "postgres://user:pass@localhost/testdb?sslmode=disable"
    db, err := sql.Open("postgres", dsn)
    if err != nil {
        t.Fatalf("failed to open test db: %v", err)
    }

    // Run migrations or schema setup here
    if err := runMigrations(db); err != nil {
        t.Fatalf("migrations failed: %v", err)
    }

    cleanup := func() {
        // Truncate all tables in reverse FK order
        tables := []string{"tokens", "users", "sessions"}
        for _, table := range tables {
            if _, err := db.Exec("TRUNCATE TABLE " + table + " RESTART IDENTITY CASCADE"); err != nil {
                t.Logf("warning: truncate %s failed: %v", table, err)
            }
        }
        db.Close()
    }

    return db, cleanup
}
```

**Usage in a test:**
```go
func TestLogin_Success(t *testing.T) {
    t.Parallel()
    db, cleanup := testutil.NewTestDB(t)
    defer cleanup()

    user := testutil.CreateTestUser(t, db, testutil.UserOpts{Email: "test@example.com"})
    svc := NewAuthService(db)

