from dataclasses import dataclass, field
from typing import Dict, Any

@dataclass
class StateContext:
    """Container for dashboard UI state."""
    user_prefs: Dict[str, Any] = field(default_factory=dict)
    cache: Dict[str, Any] = field(default_factory=dict)
    # add other fields as needed

    def update_prefs(self, prefs: Dict[str, Any]) -> None:
        self.user_prefs.update(prefs)

    def get_cached(self, key: str, default: Any = None) -> Any:
        return self.cache.get(key, default)

    def set_cached(self, key: str, value: Any) -> None:
        self.cache[key] = value

def create_state_context() -> StateContext:
    """Factory for a fresh state context (e.g., per request)."""
    return StateContext()
